PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE students (
                chat_id    TEXT PRIMARY KEY,
                naam       TEXT,
                branch     TEXT,
                roll_no    TEXT,
                unique_id  TEXT UNIQUE,
                registered_at TEXT DEFAULT (datetime('now'))
            , year TEXT, role TEXT DEFAULT 'student' CHECK(role IN ('student','admin')));
CREATE TABLE attendance (
                date       TEXT,
                chat_id    TEXT,
                status     TEXT NOT NULL,
                marked_by  TEXT NOT NULL DEFAULT 'self',
                PRIMARY KEY (date, chat_id),
                FOREIGN KEY (chat_id) REFERENCES students(chat_id)
            );
CREATE TABLE holiday_notices (
                date       TEXT PRIMARY KEY,
                notice     BLOB,
                type       TEXT NOT NULL,
                saved_by   TEXT NOT NULL
            , notify_day TEXT, announced INTEGER NOT NULL DEFAULT 0);
CREATE TABLE api_tokens (
                   token      TEXT PRIMARY KEY,
                   chat_id    TEXT NOT NULL,
                   created_at TEXT DEFAULT (datetime('now'))
               );
CREATE TABLE admin_auth (
                   chat_id    TEXT PRIMARY KEY,
                   pwd_hash   TEXT NOT NULL,
                   updated_at TEXT DEFAULT (datetime('now'))
               );
CREATE TABLE admin_reset (
                   chat_id    TEXT PRIMARY KEY,
                   code_hash  TEXT NOT NULL,
                   expires_at INTEGER NOT NULL,
                   tries      INTEGER NOT NULL DEFAULT 0,
                   created_at INTEGER NOT NULL
               );
CREATE TABLE broadcast_log (
                id         INTEGER PRIMARY KEY AUTOINCREMENT,
                kind       TEXT NOT NULL,
                day        TEXT NOT NULL,
                chat_id    TEXT NOT NULL,
                message_id INTEGER NOT NULL,
                sent_at    TEXT DEFAULT (datetime('now'))
            , batch TEXT);
CREATE TABLE recall_log (
                id         INTEGER PRIMARY KEY AUTOINCREMENT,
                day        TEXT NOT NULL,
                deleted    INTEGER NOT NULL DEFAULT 0,
                failed     INTEGER NOT NULL DEFAULT 0,
                at         TEXT DEFAULT (datetime('now'))
            );
CREATE TABLE role_audit (
                id         INTEGER PRIMARY KEY AUTOINCREMENT,
                actor_chat_id  TEXT NOT NULL,
                target_chat_id TEXT NOT NULL,
                action     TEXT NOT NULL,
                at         TEXT DEFAULT (datetime('now'))
            );
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_students_roll
                ON students(roll_no);
CREATE INDEX idx_students_branch
                ON students(branch);
CREATE INDEX idx_att_chat
                ON attendance(chat_id);
CREATE INDEX idx_bcast_day
                ON broadcast_log(kind, day);
PRAGMA writable_schema=OFF;
COMMIT;
